function Fixture.text(extra)
  local text = { generation = 2, labels = {} }
  local n = 0
  for label, body in pairs(Fixture.RAW) do
    n = n + 1
    local key = ("64:%04x"):format(0x4000 + n)
    text.labels[label] = key
    text[key] = body
  end
  for key, value in pairs(extra or {}) do text[key] = value end
  return text
end

return Fixture
